P_LHG:      equ 19H     ; LH-5811 G register
P_LHMSK:    equ 1AH     ; LH-5811 MSK: b0 IRQ, b1 PB7 (ON/BREAK key), b2 TD, b3 RD; read b5 = ON key level
P_LHIF:     equ 1BH     ; LH-5811 IF latches: b0 IRQ edge, b1 PB7 edge (ON/BREAK pressed), b2 TD, b3 RD
P_DDA:      equ 1CH     ; LH-5811 PA direction
P_DDB:      equ 1DH     ; LH-5811 PB direction
P_OPA:      equ 1EH     ; LH-5811 PA: keyboard strobe
P_OPB:      equ 1FH     ; LH-5811 PB: b7 ON/BREAK key live (1 = pressed), b6 key strobe 8, b5 1/64 s pulse, b3 BMODE.7 source, b2 cassette in
P_CPC0:     equ 20H     ; TC8576 CPC, registers 20H-27H
P_CPCPAR:   equ 21H     ; TC8576 parallel port -> sub-CPU command
P_CPCDAT:   equ 22H     ; TC8576 register data
