;------------------------------------------------------------------------------
; 4000H - ROM module header of the CE-1600F floppy driver (bank 5, 4000H)
; Module entries at +02H..+15H, the device table (X:, Y:) and a token table with
; one entry, INIT (F294H) -> 5C04H.
;------------------------------------------------------------------------------
MODID5:
	defb 43H,16H                    ; 4000  4316
B5RESET:
	jp FDRESETFN                    ; 4002  c36d40       module +02H: reset / power functions (A = 0..7)
L4005:
	ret                             ; 4005  c9           module +05H: interrupt hook (RET)
L4006:
	ret                             ; 4006  c9
L4007:
	ret                             ; 4007  c9
B5DISK:
	jp FDIOCS                       ; 4008  c31b43       module +08H: disk IOCS (C = 80H..89H, drive 1 = X, 2 = Y)
L400B:
	scf                             ; 400B  37           module +0BH: SCF / RET
	ret                             ; 400C  c9
L400D:
	ret                             ; 400D  c9
B5AUTORUN:
	jp FDAUTORUN                    ; 400E  c3b241       module +0EH: AUTORUN.BAS search
MODTAB5:
	defw B5DEVTAB                   ; 4011  2040         +11H device-name table, +13H token table
	defw 4029H                      ; 4013  2940
B5FILE:
	jp FDFILEHND                    ; 4015  c36742       module +15H: file handler
	defb 00H                        ; 4018  00
L4019:
	ret                             ; 4019  c9
	defb 0C9H,0C9H,00H              ; 401A  c9c900
L401D:
	ret                             ; 401D  c9
	defb 0C9H,0C9H                  ; 401E  c9c9
B5DEVTAB:
	defb 58H,00H,00H,00H,01H,59H,00H,00H; 4020               device names: "X" code 1, "Y" code 2
	defb 00H,02H                    ; 4028  0002
B5TOKTAB:
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 402A               token table: 39H-byte letter index (empty), one entry: INIT (F294H) -> bank 5 5C04H
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 4032
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 403A
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 4042
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 404A
	defb 00H,00H,00H,00H,00H,00H,00H,00H; 4052
	defb 00H,00H,00H,00H,00H,0AH,04H,5CH; 405A
	defb 94H,0F2H,25H,00H,00H,00H,00H,00H; 4062
	defb 00H,00H,0FFH               ; 406A  0000ff



;------------------------------------------------------------------------------
; 406DH - Floppy module reset functions (module +02H, A)
; 0/1 allocate the work area (EXROMWK C = 5, 428H bytes) and set up the drive
; table; 2 re-check; 3/4 motor off (port 81H); 5 boot search (UU := 10H if the
; boot sector of X: starts with a JP); 6 start boot (jump to work+20H); 7
; power-off handshake with the drive (port 82H b6), clears the ROM4MAP bit
; when no drive answers.
;------------------------------------------------------------------------------
FDRESETFN:
	cp 02H                          ; 406D  fe02
	jp c,FDWKALLOC                  ; 406F  da8540
	jp z,FDRECHK                    ; 4072  cad140
	cp 05H                          ; 4075  fe05
	jp c,FDMOTOROFF                 ; 4077  daf640
	jp z,FDBOOTSRCH                 ; 407A  cafa40
	cp 07H                          ; 407D  fe07
	jp c,FDBOOTGO                   ; 407F  da4941
	jp FDPOWEROFF                   ; 4082  c37741
FDWKALLOC:
	call FDPRESENT                  ; 4085  cda641
	jr c,L40B9                      ; 4088  382f
	push af                         ; 408A  f5
	ld c,05H                        ; 408B  0e05
	ld de,0428H                     ; 408D  112804
	call EXROMWK                    ; 4090  cddf02
	jr c,L40B8                      ; 4093  3823
	ld hl,(0F038H)                  ; 4095  2a38f0
	inc h                           ; 4098  24
	inc h                           ; 4099  24
	ld (hl),00H                     ; 409A  3600
